feedbackvariables.text:
/*    TESTS DES PLACEMENTS    */

/* On vérifie la présence exacte de la chaîne */
test_exact:is(ssearch("voiture:Voiture", ans1) # false);
/* On crée une liste des mots attendus pour la suite */
mots_attendus: ["Air", "Terre", "Route"];

/* On vérifie si TOUS les mots sont présents dans la réponse */
tous_presents: all_listp(lambda([x], ssearch(x, ans1) # false), mots_attendus);


/* pour les flèches*/
/* On vérifie la présence exacte des chaînes pour les objets */
test_fleche1 : is(
    (ssearch("Route-Voiture-solid", ans1) # false) or 
    (ssearch("Voiture-Route-solid", ans1) # false)
);
test_fleche1_wrong : is(
    (ssearch("Voiture-Route-dashed", ans1) # false) or 
    (ssearch("Route-Voiture-dashed", ans1) # false)
);

/* Test pour la flèche entre Air et voiture (les deux sens acceptés) */
test_fleche2 : is(
    (ssearch("Air-Voiture-solid", ans1) # false) or 
    (ssearch("Voiture-Air-solid", ans1) # false)
);
test_fleche2_wrong : is(
    (ssearch("Air-Voiture-dashed", ans1) # false) or 
    (ssearch("Voiture-Air-dashed", ans1) # false)
);

/* Test pour la flèche entre Voiture et Terre (les deux sens acceptés) */
test_fleche3 : is(
    (ssearch("Voiture-Terre-dashed", ans1) # false) or 
    (ssearch("Terre-Voiture-dashed", ans1) # false)
);
test_fleche3_wrong : is(
    (ssearch("Voiture-Terre-solid", ans1) # false) or 
    (ssearch("Terre-Voiture-solid", ans1) # false)
);

/*    TESTS DES PLACEMENTS    */

/* On vérifie la présence exacte des chaines nip enlevées*/
test_roues:is(ssearch("niproues", ans1) # false);
test_conducteur:is(ssearch("nipconducteur", ans1) # false);
test_photographe:is(ssearch("nipphotographe", ans1) # false);
/*On verifie que tout les hors système sont présents */
tous_hors_sys_ok: test_roues and test_conducteur and test_photographe;
